```js
// use forEach()
const arr1 = ["name", "age", "country"];
const arr2 = ["Jim", 54, "USA"];
const obj = {};

arr1.forEach((key, i) => {
  obj[key] = arr2[i];
});
console.log(obj); // {name: 'Jim', age: 54, country: 'USA'}

// use reduce()
const obj = arr1.reduce((accum, key, i) => {
  return { ...accum, [key]: arr2[i] };
}, {});
console.log(obj); // {name: 'Jim', age: 54, country: 'USA'}
```

