// my example: Sum All Odd Fibonacci Numbers
function sumFibs(num) {
  if (num <= 0) return 0;

  const startNums = [1, 1];
  let nextNum = 0;

  for (let i of startNums) {
    let nextNum = startNums[i - 1] + startNums[i];
    if (nextNum <= num) {
      startNums.unshift(nextNum);
    }
  }
  return startNums.filter(x => x % 2 != 0).reduce((a, b) => a + b);
}
sumFibs(4);

