    1.23e20
  )
  .toFixed(2)(
    // '123000000000000000000.00'
    1.23e-10
  )
  .toFixed(2); // '0.00'
(2.34).toFixed(1); // '2.3'
(2.35).toFixed(1); // '2.4'. Note it rounds up
(2.55).toFixed(1) - // '2.5'. Note it rounds down - see warning above
  (2.34)
    .toFixed(1)(
      //  -2.3
      -2.34
    )
    .toFixed(1); // '-2.3'
```

