  } else if (value === "") {
    delete records[id][prop];
  }
  return records;
}

// Example, RECORD COLLECTION 2:
function updateRecords(records, id, prop, value) {
  if (value === '') {
    delete records[id][prop];
  } else if (prop === 'tracks') {
    records[id][prop] = records[id][prop] || []; // this is called shortcircuit evaluation, see below for explanation
