    return `${this.firstName} ${this.lastName}`
  }
}
const student1 = new Student("Mary", "Williams", "Junior", "A");
console.log(student1); // Student {firstName: 'Mary', lastName: 'Williams', gradeLevel: 'Junior', currentAverage: 'A'}

